 date","type":"date","required":true},{"key":"reminder_date","label":"Next reminder date","type":"date","required":false},{"key":"invoice_number","label":"Invoice number","required":false},{"key":"purchase_id","label":"Purchase UUID","required":false},{"key":"notes","label":"Notes","type":"textarea","required":false}]}}'::jsonb);
